sources = {
    1: "The Falcon plan costs twenty dollars per month and includes ten projects.",
}

def build_structured_output_prompt(sources, query):
    # assemble the labeled context block from the source dict
    context_block = "\n".join(f"[{k}] {v}" for k, v in sources.items())
    template = (
        "Answer:\n"
        "Confidence: [high, medium, or low]\n"
        "Sources: [comma separated source numbers, or none]"
    )
    return (
        f"Context:\n{context_block}\n\n"
        f"Question: {query}\n"
        f"Respond using exactly this template:\n{template}"
    )

query = "What does the Falcon plan cost?"
prompt = build_structured_output_prompt(sources, query)
print("Structured output prompt:\n")
print(prompt)

def parse_structured_response(response_text):
    # split each labeled line into a field name and value
    fields = {}
    for line in response_text.strip().split("\n"):
        if ":" in line:
            key, _, value = line.partition(":")
            fields[key.strip().lower()] = value.strip()
    return fields

simulated_response = (
    "Answer: The Falcon plan costs twenty dollars per month.\n"
    "Confidence: high\n"
    "Sources: 1"
)
parsed = parse_structured_response(simulated_response)
print("\nParsed fields:")
print(parsed)
